fork
:Govern PWM fans;
fork again
:Govern liquid-cooling loop;
end fork

if(External ambient exceeds set threshold?) then(yes)
:Temperature sensor ISR triggered;
:Initiate data validation sequence;
else (no)
endif

if (Primary sensor reading erroneous?) then(yes)
:Fail over to redundant sensor path;
else (no)
endif

if(Sensor over-temperature confirmed?) then(yes)
