  else (yes)
  endif

repeat 
:Poll for temperature fluctuations;
repeat while(Values re-enter safe operating range) is(no)

else (no)
endif

fork

:Log data to ring buffer;
fork
:Operational data;
fork again
:Fault events;
end fork

:Analysis and service report generation;

fork again
:Telemetry monitor executes in timed loop;
fork again
:Sensor fusion and calibration routines run periodically;
end fork

:Maintain system integrity;

stop
@enduml

